CREATE TABLE workday_earnings (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, workday_id BIGINT NOT NULL UNIQUE REFERENCES workdays(id), local_date DATE NOT NULL, reference_month VARCHAR(7) NOT NULL, status VARCHAR(16) NOT NULL, economic_seconds BIGINT NOT NULL, raw_amount NUMERIC(24,12), salary_profile_id BIGINT, income_source VARCHAR(32), monthly_net NUMERIC(19,2), annual_net NUMERIC(19,2), pay_periods INTEGER, currency_code VARCHAR(3), standard_hours NUMERIC(24,12), hourly_rate NUMERIC(24,12), materialized_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_workday_earnings_date ON workday_earnings(local_date);
